"""Voice benchmark run manifest for Coval ↔ Rasa correlation."""

from __future__ import annotations

import hashlib
import json
import re
import uuid
from dataclasses import asdict, dataclass
from typing import Any, Dict, List, Optional, Sequence

from rasa.builder.copilot.mcp_server.tools.scenario import Scenario

_MAX_RASA_SENDER_ID_LENGTH = 128
_INVALID_RASA_SENDER_ID_CHARS = re.compile(r"[^A-Za-z0-9._:-]")
_RASA_SENDER_ID_PREFIX = "voice-"


def _sanitize_scenario_slug_for_sender_id(slug: str) -> str:
    """Return a slug fragment safe for Coval external sender ids."""
    sanitized = _INVALID_RASA_SENDER_ID_CHARS.sub("_", slug).strip("_")
    return sanitized or "scenario"


def _build_rasa_sender_id(
    scenario_slug: str,
    run_index: int,
    run_suffix: str,
) -> str:
    """Build a sender id that passes Coval header validation."""
    suffix_part = f"-{run_index}-{run_suffix}"
    sanitized_slug = _sanitize_scenario_slug_for_sender_id(scenario_slug)
    max_slug_chars = (
        _MAX_RASA_SENDER_ID_LENGTH - len(_RASA_SENDER_ID_PREFIX) - len(suffix_part)
    )
    if max_slug_chars <= 0:
        hashed = hashlib.sha256(scenario_slug.encode()).hexdigest()[:8]
        return f"{_RASA_SENDER_ID_PREFIX}{hashed}{suffix_part}"
    if len(sanitized_slug) > max_slug_chars:
        sanitized_slug = sanitized_slug[:max_slug_chars]
    return f"{_RASA_SENDER_ID_PREFIX}{sanitized_slug}{suffix_part}"


@dataclass(frozen=True)
class VoiceRunManifestEntry:
    """One logical voice benchmark repetition."""

    scenario_slug: str
    test_case_id: str
    run_index: int
    rasa_sender_id: str
    initial_slots: Dict[str, Any]


def build_voice_run_manifest(
    *,
    scenario: Scenario,
    test_case_id: str,
    run_count: int,
    run_suffix: Optional[str] = None,
) -> List[VoiceRunManifestEntry]:
    """Build manifest entries for one scenario repeated ``run_count`` times.

    Sender ids include a per-benchmark-run suffix so trackers never collide
    across successive benchmark invocations.
    """
    suffix = run_suffix or uuid.uuid4().hex[:8]
    return [
        VoiceRunManifestEntry(
            scenario_slug=scenario.slug,
            test_case_id=test_case_id,
            run_index=index,
            rasa_sender_id=_build_rasa_sender_id(scenario.slug, index, suffix),
            initial_slots=dict(scenario.setup.initial_slots),
        )
        for index in range(1, run_count + 1)
    ]


def manifest_to_json(entries: Sequence[VoiceRunManifestEntry]) -> str:
    """Serialize manifest entries to JSON."""
    return json.dumps([asdict(entry) for entry in entries], indent=2)


def manifest_from_json(payload: str) -> List[VoiceRunManifestEntry]:
    """Deserialize manifest entries from JSON."""
    raw = json.loads(payload)
    if not isinstance(raw, list):
        raise ValueError("manifest JSON must be a list")
    return [
        VoiceRunManifestEntry(
            scenario_slug=str(item["scenario_slug"]),
            test_case_id=str(item["test_case_id"]),
            run_index=int(item["run_index"]),
            rasa_sender_id=str(item["rasa_sender_id"]),
            initial_slots=dict(item.get("initial_slots") or {}),
        )
        for item in raw
    ]
